<script setup>import {computed} from 'vue';import {useApp} from '../stores/app';import {money,day} from '../services/storage';import PageTitle from '../components/PageTitle.vue';const s=useApp();const today=computed(()=>s.paid.filter(o=>o.date===day()));const revenue=computed(()=>today.value.reduce((a,o)=>a+o.total,0));const top=computed(()=>{const m={};for(const o of s.paid)for(const l of o.lines)m[l.name]=(m[l.name]||0)+l.qty;return Object.entries(m).sort((a,b)=>b[1]-a[1])})</script><template><PageTitle :title="'Halo, '+s.user.name+'!'" subtitle="Ringkasan aktivitas outlet hari ini."/><div class="metrics"><article class="card"><small>Penjualan hari ini</small><h2>{{money(revenue)}}</h2></article><article class="card"><small>Pesanan hari ini</small><h2>{{today.length}}</h2></article><article class="card"><small>Rata-rata transaksi</small><h2>{{money(today.length?revenue/today.length:0)}}</h2></article><article class="card"><small>Stok menipis</small><h2>{{s.low.length}}</h2></article></div><section class="card"><h2>Menu terlaris · seluruh periode</h2><p v-if="!top.length">Belum ada transaksi.</p><div v-for="[name,qty] in top" :key="name"><div class="spread"><p>{{name}}</p><b>{{qty}} cup</b></div><progress :value="qty" :max="top[0][1]"/></div></section></template>
